def compute(vars):
    old_value = vars["v1"]
    new_value = vars["v2"]
    change = new_value - old_value
    change_ratio = None if old_value == 0 else change / old_value
    percentage_change = None if change_ratio is None else change_ratio * 100

    return {
        "value": percentage_change,
        "trace": {
            "old_value_2018": old_value,
            "new_value_2019": new_value,
            "change": change,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
